#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
vector<long long>x(n),y(n);
for(int i=0;i<n;++i)scanf("%lld %lld",&x[i],&y[i]);
const long long INF=4e18;
vector<long long>dist(n,INF);vector<bool>used(n,false);
dist[0]=0;long long total=0;
for(int it=0;it<n;++it){
int u=-1;
for(int i=0;i<n;++i)if(!used[i]&&(u==-1||dist[i]<dist[u]))u=i;
used[u]=true;total+=dist[u];
for(int v=0;v<n;++v)if(!used[v]){
long long d=llabs(x[u]-x[v])+llabs(y[u]-y[v]);
if(d<dist[v])dist[v]=d;}}
printf("%lld\n",total);return 0;}

